export interface FoodCatalogEntry {
  name: string;
  kgPerPortion: number;
  /** Synthetic "truth": share of diners who take the item. */
  uptake: number;
  /** Synthetic effect on attendance when the dish is on the menu. */
  pull: number;
  /** Synthetic tendency of managers to prepare extra of this item. */
  overprep: number;
}

const f = (name: string, kgPerPortion: number, uptake: number, pull = 0, overprep = 0): FoodCatalogEntry => ({
  name,
  kgPerPortion,
  uptake,
  pull,
  overprep,
});

